+	msg.header = PD_HEADER_EXT_LE(PD_EXT_BATT_CAP, port->pwr_role,
+				      port->data_role, port->negotiated_rev,
+				      port->message_id, data_obj_cnt);
+
+	return tcpm_pd_transmit(port, TCPC_TX_SOP, &msg);
+}
